package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class TypeHandlerTest {

    // Helper to create a Converter proxy instance
    @SuppressWarnings("unchecked")
    private Converter<Object, Throwable> createConverterProxy() {
        InvocationHandler handler = (proxy, method, args) -> null;
        return (Converter<Object, Throwable>)
                Proxy.newProxyInstance(
                        Converter.class.getClassLoader(),
                        new Class[]{Converter.class},
                        handler
                );
    }

    @Test
    void testGetConverterReturnsMappedConverter() {
        Converter<Object, Throwable> proxy = createConverterProxy();

        @SuppressWarnings("unchecked")
        Map<Class<?>, Converter<?, ? extends Throwable>> map = new HashMap<>();
        map.put(String.class, (Converter<?, ? extends Throwable>) proxy);

        TypeHandler handler = new TypeHandler(map);

        Converter<?, ?> result = handler.getConverter(String.class);
        assertSame(proxy, result, "Expected the mapped converter to be returned");
    }

    @Test
    void testGetConverterReturnsDefaultWhenAbsent() {
        @SuppressWarnings("unchecked")
        Map<Class<?>, Converter<?, ? extends Throwable>> map = new HashMap<>();
        TypeHandler handler = new TypeHandler(map);

        Converter<?, ?> result = handler.getConverter(Integer.class);
        assertSame(Converter.DEFAULT, result, "Expected Converter.DEFAULT when no mapping exists");
    }

    @Test
    void testGetConverterWithNullKeyReturnsMappedConverter() {
        Converter<Object, Throwable> proxy = createConverterProxy();

        @SuppressWarnings("unchecked")
        Map<Class<?>, Converter<?, ? extends Throwable>> map = new HashMap<>();
        map.put(null, (Converter<?, ? extends Throwable>) proxy);

        TypeHandler handler = new TypeHandler(map);

        Converter<?, ?> result = handler.getConverter(null);
        assertSame(proxy, result, "Expected the converter mapped to null key to be returned");
    }

    @Test
    void testGetConverterSubclassNotMappedReturnsDefault() {
        Converter<Object, Throwable> numberConverter = createConverterProxy();

        @SuppressWarnings("unchecked")
        Map<Class<?>, Converter<?, ? extends Throwable>> map = new HashMap<>();
        // map Number.class only
        map.put(Number.class, (Converter<?, ? extends Throwable>) numberConverter);

        TypeHandler handler = new TypeHandler(map);

        // Integer.class is not mapped exactly, expect DEFAULT
        Converter<?, ?> result = handler.getConverter(Integer.class);
        assertSame(Converter.DEFAULT, result, "Expected Converter.DEFAULT when subclass key is not present");
    }

    @Test
    void testConstructorNullMapThrowsNPE() {
        assertThrows(NullPointerException.class, () -> new TypeHandler(null));
    }

    @Test
    void testGetDefaultMatchesPrivateDefaultField() throws Exception {
        // Use reflection to read the private static DEFAULT field
        Field defaultField = TypeHandler.class.getDeclaredField("DEFAULT");
        defaultField.setAccessible(true);
        Object privateDefault = defaultField.get(null);

        // Validate getDefault() returns the same instance
        TypeHandler viaMethod = TypeHandler.getDefault();
        assertSame(privateDefault, viaMethod, "TypeHandler.getDefault() should return the private DEFAULT instance");
    }
